// work.alert.raise — automatic alerts as actions (R15 first). Generated by `pnpm gen:command`; acceptance cases
// added.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { aStaffActor, countRows, createFakeClock, runAsOwner } from '@ocs/testing';
import { Forbidden, systemActor, ValidationFailed } from '../../kernel/index.ts';
import { raiseAlert } from '../commands/raise-alert.ts';
import { openWorkWorld, type WorkWorld } from './fixture.ts';

const job = systemActor('alerts');
const pm = aStaffActor({ roles: ['pm'] });
const clock = createFakeClock(new Date('2026-11-04T12:00:00Z'));
let w: WorkWorld;
const alert = (ref: string, siteId = w.siteId) => ({
  siteId,
  ref,
  title: `Device ${ref} offline — find the cause`,
});
const raise = (...alerts: ReturnType<typeof alert>[]) =>
  w.t.kernel.execute(raiseAlert, job, { alerts }, 'system');
const actions = (where: string, params: unknown[] = []) =>
  countRows(w.testDb.url, `action WHERE ${where}`, params);

beforeAll(async () => {
  w = await openWorkWorld({ clock: clock.now });
  w.t.grant(job, raiseAlert.permission);
  await runAsOwner(w.testDb.url, `UPDATE site SET pm_id = $2 WHERE id = $1`, [w.siteId, pm.id]);
});

afterAll(async () => {
  await w.close();
});

describe('work.alert.raise', () => {
  it('refuses anyone but the system actor, and a bad alert', async () => {
    await expect(w.t.kernel.execute(raiseAlert, pm, { alerts: [] }, 'test')).rejects.toBeInstanceOf(
      Forbidden,
    );
    await expect(raise({ ...alert('R15:a'), ref: ' ' })).rejects.toBeInstanceOf(ValidationFailed);
  });

  it("raises an internal action owned by the project's PM, due the next day, sourced from the alert", async () => {
    const r = await raise(alert('R15:dev-1:2026-11-03T10:00:00.000Z'));
    expect(r.created).toHaveLength(1);
    expect(
      await actions(
        `source_kind = 'alert' AND source_ref = $1 AND owner_id = $2 AND due = '2026-11-05' AND visibility = 'internal'`,
        ['R15:dev-1:2026-11-03T10:00:00.000Z', pm.id],
      ),
    ).toBe(1);
    expect(await countRows(w.testDb.url, `outbox WHERE event_type = 'work.action.created'`)).toBe(1);
  });

  it('the same episode is raised once, even after its action is done; a new episode raises a new one', async () => {
    await runAsOwner(
      w.testDb.url,
      `UPDATE action SET status = 'done', done_at = now() WHERE source_ref = $1`,
      ['R15:dev-1:2026-11-03T10:00:00.000Z'],
    );
    const again = await raise(
      alert('R15:dev-1:2026-11-03T10:00:00.000Z'),
      alert('R15:dev-1:2026-11-04T08:00:00.000Z'),
    );
    expect([again.created.length, again.existing]).toEqual([1, 1]);
    expect(await actions(`source_ref LIKE 'R15:dev-1:%'`)).toBe(2);
  });

  it('a project without a PM or gone is reported and skipped; the rest of the run goes on', async () => {
    await runAsOwner(w.testDb.url, `UPDATE site SET pm_id = NULL WHERE id = $1`, [w.siteId]);
    const r = await raise(alert('R15:dev-2:x'), alert('R15:dev-3:x', randomUUID()));
    expect(r.skipped).toEqual([
      { ref: 'R15:dev-2:x', reason: 'no_pm' },
      { ref: 'R15:dev-3:x', reason: 'no_project' },
    ]);
    expect(await countRows(w.testDb.url, 'audit_event WHERE command = $1', [raiseAlert.name])).toBe(3);
  });
});
